from itertools import product

# Define the length of the sequence
n = 19

# Define the fixed values
fixed_values = {4: -1, 12: 1, 13: -1}

c = {1: -1, 2: 0, 7: -3}

# Generate all possible sequences
for seq in product([-1, 1], repeat=n):
    # Check if the sequence satisfies the fixed values
    if all(seq[i] == fixed_values[i] for i in fixed_values):
        # Calculate the autocorrelation
        autocorrelation = sum(sum(seq[i] * seq[i + k] for i in range(n - k)) ** 2 for k in range(1, n))

        # Check if the autocorrelation is at most 46
        if autocorrelation <= 46:
            # Check if the sequence satisfies the fixed autocorrelation values
            for k in c:
                if sum(seq[i] * seq[i + k] for i in range(n - k)) != c[k]:
                    break
            else:
                print(seq)
                break
else:
    print("UNSATISFIABLE")
